using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

var builder = Host.CreateApplicationBuilder(args);

// Redirect all logging to stderr so stdout stays clean for JSON-RPC
builder.Logging.AddConsole(options =>
    options.LogToStandardErrorThreshold = LogLevel.Trace);

// Register HttpClient for DI into tool classes
builder.Services.AddHttpClient("Api", client =>
{
    client.BaseAddress = new Uri("https://jsonplaceholder.typicode.com");
});

// Register MCP server with stdio transport and auto-discover tools
builder.Services.AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

await builder.Build().RunAsync();

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public class ApiTools(IHttpClientFactory httpClientFactory, ILogger<ApiTools> logger)
{
    [McpServerTool, Description("Get a post by its numeric ID from the REST API.")]
    public async Task<string> GetPost(
        [Description("The numeric ID of the post (1-100)")] int id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching post {Id}", id);
        var client = httpClientFactory.CreateClient("Api");
        var json = await client.GetStringAsync($"/posts/{id}", cancellationToken);
        return json;
    }

    [McpServerTool, Description("List all posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Filter posts by this user ID (optional)")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var client = httpClientFactory.CreateClient("Api");
        var url = userId.HasValue ? $"/posts?userId={userId}" : "/posts";
        var json = await client.GetStringAsync(url, cancellationToken);
        return json;
    }

    [McpServerTool, Description("Create a new post with a title, body, and user ID.")]
    public async Task<string> CreatePost(
        [Description("Title of the post")] string title,
        [Description("Body content of the post")] string body,
        [Description("ID of the user authoring the post")] int userId,
        CancellationToken cancellationToken = default)
    {
        var client = httpClientFactory.CreateClient("Api");
        var payload = new { title, body, userId };
        var response = await client.PostAsJsonAsync("/posts", payload, cancellationToken);
        response.EnsureSuccessStatusCode();
        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        return json;
    }
}

